'use strict';

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

// Parser states.
const RECORD_START = 0; // nothing of the current record has been read
const FIELD_START = 1; // just after a delimiter
const UNQUOTED = 2;
const QUOTED = 3;
// A `"` inside a quoted field: either the closing quote or the first half of `""`.
const QUOTE_IN_QUOTED = 4;

const EOLS = ['\r\n', '\n'];

/** An error in the CSV input. `line` and `column` are 1-based; columns count UTF-16 code units. */
class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

// For error messages: strings are shown quoted, other values by type.
function show(value) {
  return typeof value === 'string' ? JSON.stringify(value) : describe(value);
}

function checkOptions(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError(`options must be an object, got ${describe(options)}`);
  }
}

function readDelimiter(delimiter) {
  if (delimiter === undefined) return ',';
  if (typeof delimiter !== 'string' || delimiter.length !== 1) {
    throw new TypeError(`delimiter must be a single character, got ${show(delimiter)}`);
  }
  const code = delimiter.charCodeAt(0);
  // A lone surrogate is half of a character, not a character.
  if (code === QUOTE || code === CR || code === LF || (code >= 0xd800 && code <= 0xdfff)) {
    throw new TypeError(`delimiter cannot be ${show(delimiter)}`);
  }
  return delimiter;
}

function readFlag(options, name) {
  const value = options[name];
  if (value !== undefined && typeof value !== 'boolean') {
    throw new TypeError(`${name} must be a boolean, got ${describe(value)}`);
  }
  return value === true;
}

// Assigning to `__proto__` on a plain object would set its prototype instead of creating a key.
function toObject(names, values) {
  const object = {};
  for (let i = 0; i < names.length; i++) {
    if (names[i] === '__proto__') {
      Object.defineProperty(object, names[i], { value: values[i], writable: true, enumerable: true, configurable: true });
    } else {
      object[names[i]] = values[i];
    }
  }
  return object;
}

/**
