 * `chunk`; `end()` returns the last record, if any. Once either method throws, or after `end()`,
 * both throw. Each input character is examined once, whatever the chunk boundaries.
 */
function createParser(options = {}) {
  checkOptions(options);
  const delimiter = readDelimiter(options.delimiter).charCodeAt(0);
  const header = readFlag(options, 'header');
  const skipEmptyLines = readFlag(options, 'skipEmptyLines');

  let state = RECORD_START;
  let started = false; // whether any input has arrived; a BOM is only stripped from the first character
  let finished = false;
  let afterCR = false; // the previous character was a CR, so an LF now completes a CRLF
  // Position of the next character.
  let line = 1;
  let column = 1;
  let recordLine = 1;
  let fieldLine = 1;
  let fieldColumn = 1;
  // Pieces of the current field that were cut off by a chunk boundary or an escaped quote.
  const parts = [];
  let record = [];
  let names = null; // column names, once the header record has been read
  let seenNames = header ? new Set() : null; // set while the header record is being read
  let completed = [];

  function takeField() {
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return value;
  }

  function pushPart(chunk, from, to) {
    if (to > from) parts.push(chunk.slice(from, to));
  }

  function endField(value) {
    if (seenNames !== null) {
      if (seenNames.has(value)) {
        throw new CsvError(`Duplicate column name ${JSON.stringify(value)}`, fieldLine, fieldColumn);
      }
      seenNames.add(value);
    }
    record.push(value);
  }

  function endRecord() {
    const fields = record;
    record = [];
    state = RECORD_START;
    if (!header) {
      completed.push(fields);
    } else if (names === null) {
      names = fields;
      seenNames = null;
    } else if (fields.length !== names.length) {
      throw new CsvError(`Expected ${names.length} fields but found ${fields.length}`, recordLine, 1);
    } else {
      completed.push(toObject(names, fields));
    }
