        column = 1;
      } else if (c !== LF) {
        column++;
      }
    }

    if (state === UNQUOTED || state === QUOTED) pushPart(chunk, runStart, chunk.length);
  }

  function finish() {
    if (state === QUOTED) throw new CsvError('Quoted field is never closed', fieldLine, fieldColumn);
    if (state === FIELD_START) {
      // The input ended right after a delimiter, so the empty last field starts here.
      fieldLine = line;
      fieldColumn = column;
    }
    if (state !== RECORD_START) {
      endField(takeField());
      endRecord();
    }
  }

  function run(step) {
    if (finished) throw new Error('The CSV parser has already ended or failed; create a new parser');
    try {
      step();
    } catch (err) {
      finished = true;
      throw err;
    }
    const records = completed;
    completed = [];
    return records;
  }

  return {
    write(chunk) {
      return run(() => {
        if (typeof chunk !== 'string') throw new TypeError(`chunk must be a string, got ${describe(chunk)}`);
        consume(chunk);
      });
    },
    end() {
      return run(() => {
