  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && row !== null && typeof row === 'object') {
      values = header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
    } else {
      const expected = header === null ? 'an array' : 'an array or an object';
      throw new TypeError(`row ${rowIndex} must be ${expected}, got ${describe(row)}`);
    }
    lines.push(formatRecord(values, delimiter, rowIndex, lines.length === 0));
  }
  return lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

