function finish() {
  if (state === QUOTED) throw new CsvError('Quoted field is never closed', fieldLine, fieldColumn);
  if (state === FIELD_START) {
    // The input ended right after a delimiter, so the empty last field starts here.
    fieldLine = line;
    fieldColumn = column;
  }
  if (state === UNQUOTED) {
    endField(trim ? trimEnd(takeField()) : takeField());
    endRecord();
  } else if (state !== RECORD_START && state !== COMMENT) {
    endField(takeField());
    endRecord();
  }
}

